// TestNotFoundReturnsNotFoundError maps a 404 to its status family's error type.
func TestNotFoundReturnsNotFoundError(t *testing.T) {
	stub := newStub(t, stubReply{status: 404, body: `{"message":"Not found"}`})
	client := newClient(t, stub, apiclient.WithCredential("apiKey", "test-token"))
	_, err := client.Organization.Get(context.Background())
	var notFound *apiclient.NotFoundError
	if !errors.As(err, &notFound) {
		t.Fatalf("error = %v, want *NotFoundError", err)
	}
	if notFound.Status != 404 {
		t.Fatalf("status = %d, want 404", notFound.Status)
	}
}

// TestPaginationWalksTwoPages follows the first page to the second.
func TestPaginationWalksTwoPages(t *testing.T) {
	stub := newStub(t,
		stubReply{status: 200, body: `{"object":"list","data":[{"id":"prj_4f8k2m7x9q1v6b3n","object":"project","name":"example","spec_id":"spec_2p8m4q7k1v9d6h3c","auto_generate":true,"config":{"globals":["example"],"include":["example"],"exclude":["example"],"retries":{"max_retries":1,"statuses":[1],"initial_delay_ms":1,"max_delay_ms":1,"retry_non_idempotent":true,"disabled":true,"operations":{}},"pagination":{},"auth":{"oauth_server":{"issuer":"https://example.com","discovery_url":"https://example.com","authorization_url":"https://example.com","token_url":"https://example.com","device_authorization_url":"https://example.com","scopes":["S123"],"audience":"example","resource":"https://example.com"},"oauth_applications":{},"oauth_application":"example","identity_verification":{"subject_field":"/id","account_field":"/account_id","organization_field":"/organization_id"},"approval_url":"https://example.com","environments":{},"credential_variables":{},"credential_parameters":{}},"cli":{"command_name":"example","changelog_url":"https://example.com","support_url":"https://example.com","mcp_url":"https://example.com","skills_repo":"example"},"mcp":{"registry_name":"example","access":{"issuer":"https://example.com","resource":"https://example.com","jwks_url":"https://example.com","scopes":["example"]},"tool_mode":"auto","instructions":"Hello, world!","tool_descriptions":{},"reference_resolvers":{}},"readme":{"quickstart_operation":"example"},"package":{"title":"Hello, world","homepage":"https://example.com","license":"example","license_text":"example","copyright":"example","go_package_name":"example"},"docs_url":"https://example.com","docs_index_url":"https://example.com"},"created_at":"2026-01-15T12:00:00Z","updated_at":"2026-01-15T12:00:00Z","request_id":"req_3k8m1v6q9p2d7h4c"}],"has_more":true,"next_cursor":"cursor_test_2","request_id":"req_3k8m1v6q9p2d7h4c"}`},
		stubReply{status: 200, body: `{"object":"list","data":[{"id":"prj_4f8k2m7x9q1v6b3n","object":"project","name":"example","spec_id":"spec_2p8m4q7k1v9d6h3c","auto_generate":true,"config":{"globals":["example"],"include":["example"],"exclude":["example"],"retries":{"max_retries":1,"statuses":[1],"initial_delay_ms":1,"max_delay_ms":1,"retry_non_idempotent":true,"disabled":true,"operations":{}},"pagination":{},"auth":{"oauth_server":{"issuer":"https://example.com","discovery_url":"https://example.com","authorization_url":"https://example.com","token_url":"https://example.com","device_authorization_url":"https://example.com","scopes":["S123"],"audience":"example","resource":"https://example.com"},"oauth_applications":{},"oauth_application":"example","identity_verification":{"subject_field":"/id","account_field":"/account_id","organization_field":"/organization_id"},"approval_url":"https://example.com","environments":{},"credential_variables":{},"credential_parameters":{}},"cli":{"command_name":"example","changelog_url":"https://example.com","support_url":"https://example.com","mcp_url":"https://example.com","skills_repo":"example"},"mcp":{"registry_name":"example","access":{"issuer":"https://example.com","resource":"https://example.com","jwks_url":"https://example.com","scopes":["example"]},"tool_mode":"auto","instructions":"Hello, world!","tool_descriptions":{},"reference_resolvers":{}},"readme":{"quickstart_operation":"example"},"package":{"title":"Hello, world","homepage":"https://example.com","license":"example","license_text":"example","copyright":"example","go_package_name":"example"},"docs_url":"https://example.com","docs_index_url":"https://example.com"},"created_at":"2026-01-15T12:00:00Z","updated_at":"2026-01-15T12:00:00Z","request_id":"req_3k8m1v6q9p2d7h4c"}],"has_more":false,"next_cursor":"","request_id":"req_3k8m1v6q9p2d7h4c"}`},
		stubReply{status: 200, body: `{"object":"list","data":[],"has_more":false,"next_cursor":"","request_id":"req_3k8m1v6q9p2d7h4c"}`},
	)
	client := newClient(t, stub, apiclient.WithCredential("apiKey", "test-token"))
	params := apiclient.ProjectsListParams{}
	it := client.Projects.List(context.Background(), &params)
	count := 0
	for it.Next() {
		count++
	}
	if err := it.Err(); err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Fatalf("items = %d, want 2", count)
	}
	if got := stub.request(t, 1).query.Get("cursor"); got != "cursor_test_2" {
		t.Fatalf("second request cursor = %q, want cursor_test_2", got)
	}
}
